import math

def is_prime(n):
    """Checks if a number n is a positive prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def safe_integer_power(base, exp):
    """
    Calculates base^exp, returning the result and a boolean indicating if it's an integer.
    Returns None if the result is not an integer (e.g., 2^(-1)).
    Assumes base != 0.
    """
    if exp >= 0:
        return base ** exp, True
    else:
        # exp < 0. base^exp = 1 / base^(-exp)
        if abs(base) == 1:
            # 1^E = 1, (-1)^E = +/- 1 (integer)
            return base ** exp, True
        else:
            # 1 / (integer > 1) is fractional, thus not an integer
            return None, False

def evaluate_N(x, y, z):
    """
    Evaluates N = y^x * z^y * x^z, checking if N is a positive prime integer.
    Returns (N, True) if N is a positive prime integer, otherwise returns (None, False).
